    map['code'] = Variable<String>(code);
    map['name'] = Variable<String>(name);
    map['account_type'] = Variable<String>(accountType);
    if (!nullToAbsent || parentRemoteId != null) {
      map['parent_remote_id'] = Variable<String>(parentRemoteId);
    }
    if (!nullToAbsent || accountGroup != null) {
      map['account_group'] = Variable<String>(accountGroup);
    }
    map['is_active'] = Variable<bool>(isActive);
    map['opening_balance_paise'] = Variable<int>(openingBalancePaise);
    map['sync_status'] = Variable<String>(syncStatus);
    if (!nullToAbsent || lastSyncedAt != null) {
      map['last_synced_at'] = Variable<DateTime>(lastSyncedAt);
    }
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

