class Contact extends DataClass implements Insertable<Contact> {
  final String localId;
  final String remoteId;
  final String companyId;
  final String name;
  final String? email;
  final String? phone;

  /// One of: `'customer'`, `'vendor'`, `'both'`.
  final String contactType;
  final String? gstin;
  final String? stateCode;

  /// Tenant-scoped control accounts provisioned by the server. Financial
  /// transactions must use these IDs instead of a contact UUID.
  final String? receivableAccountId;
  final String? payableAccountId;
  final bool isActive;

  /// Opening balance in paise.
  final int openingBalancePaise;
  final String syncStatus;
  final DateTime? lastSyncedAt;
  final DateTime updatedAt;
  const Contact({
    required this.localId,
    required this.remoteId,
    required this.companyId,
    required this.name,
    this.email,
    this.phone,
    required this.contactType,
    this.gstin,
    this.stateCode,
    this.receivableAccountId,
    this.payableAccountId,
    required this.isActive,
    required this.openingBalancePaise,
    required this.syncStatus,
    this.lastSyncedAt,
    required this.updatedAt,
  });
