    required this.lifecycleStatus,
    required this.syncStatus,
    required this.localRevision,
    this.remoteRevision,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    this.lastSyncedAt,
    this.syncError,
    required this.isDirty,
    required this.originDeviceId,
  });
