class InvoiceLine extends DataClass implements Insertable<InvoiceLine> {
  final String localId;
  final String invoiceLocalId;
  final String? productId;
  final String productName;
  final String? description;
  final String? hsnSac;

  /// Unit price in paise (or paise-equivalent for precision).
  final int unitPricePaise;

  /// Quantity — stored as TEXT for arbitrary precision (e.g. "10.500").
  final String quantity;
  final int amountPaise;
  final int discountPaise;

  /// Net line total (amount - discount) before tax.
  final int netPaise;
  final int taxRateBasisPoints;
  final int taxPaise;
  final int sortOrder;
  const InvoiceLine({
    required this.localId,
    required this.invoiceLocalId,
    this.productId,
    required this.productName,
    this.description,
    this.hsnSac,
    required this.unitPricePaise,
    required this.quantity,
    required this.amountPaise,
    required this.discountPaise,
    required this.netPaise,
    required this.taxRateBasisPoints,
    required this.taxPaise,
    required this.sortOrder,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['local_id'] = Variable<String>(localId);
    map['invoice_local_id'] = Variable<String>(invoiceLocalId);
    if (!nullToAbsent || productId != null) {
      map['product_id'] = Variable<String>(productId);
    }
    map['product_name'] = Variable<String>(productName);
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    if (!nullToAbsent || hsnSac != null) {
      map['hsn_sac'] = Variable<String>(hsnSac);
    }
    map['unit_price_paise'] = Variable<int>(unitPricePaise);
    map['quantity'] = Variable<String>(quantity);
    map['amount_paise'] = Variable<int>(amountPaise);
    map['discount_paise'] = Variable<int>(discountPaise);
    map['net_paise'] = Variable<int>(netPaise);
    map['tax_rate_basis_points'] = Variable<int>(taxRateBasisPoints);
    map['tax_paise'] = Variable<int>(taxPaise);
    map['sort_order'] = Variable<int>(sortOrder);
    return map;
  }

  InvoiceLinesCompanion toCompanion(bool nullToAbsent) {
    return InvoiceLinesCompanion(
      localId: Value(localId),
      invoiceLocalId: Value(invoiceLocalId),
      productId: productId == null && nullToAbsent
          ? const Value.absent()
          : Value(productId),
      productName: Value(productName),
      description: description == null && nullToAbsent
          ? const Value.absent()
          : Value(description),
      hsnSac: hsnSac == null && nullToAbsent
          ? const Value.absent()
          : Value(hsnSac),
      unitPricePaise: Value(unitPricePaise),
      quantity: Value(quantity),
      amountPaise: Value(amountPaise),
      discountPaise: Value(discountPaise),
      netPaise: Value(netPaise),
      taxRateBasisPoints: Value(taxRateBasisPoints),
      taxPaise: Value(taxPaise),
      sortOrder: Value(sortOrder),
    );
  }

